//! Generic Document identity is independent from the HTML/XML document flag.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://attribute-factories.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}


#[test]
fn node_namespace_lookup_canonical_methods_real_interfaces_and_native_node_contexts(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var uri=Node.prototype.lookupNamespaceURI,prefix=Node.prototype.lookupPrefix;for(var pair of [['lookupNamespaceURI',uri],['lookupPrefix',prefix]]){var d=Object.getOwnPropertyDescriptor(Node.prototype,pair[0]);if(pair[1].name!==pair[0]||pair[1].length!==1||!d.enumerable||!d.writable||!d.configurable)throw 'native Node method descriptor';for(var bad of [{},Node.prototype,null]){var caught=false;try{pair[1].call(bad,'p');}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'native receiver brand';}var caught=false;try{pair[1].call(document);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'required namespace argument';}
var xml=document.implementation.createDocument('urn:original','p:Root'),root=xml.documentElement,child=xml.createElement('Child'),text=xml.createTextNode('data'),comment=xml.createComment('marker'),cdata=xml.createCDATASection('data'),pi=xml.createProcessingInstruction('target','data'),attr=xml.createAttribute('held');root.appendChild(child);child.appendChild(text);child.appendChild(comment);child.appendChild(cdata);child.appendChild(pi);child.setAttributeNode(attr);for(var node of [xml,root,child,text,comment,cdata,pi,attr]){if(uri.call(node,'p')!=='urn:original'||prefix.call(node,'urn:original')!=='p'||uri.call(node,'xml')!=='http://www.w3.org/XML/1998/namespace'||uri.call(node,'xmlns')!=='http://www.w3.org/2000/xmlns/'||prefix.call(node,null)!==null||prefix.call(node,'')!==null)throw 'actual Node context and built-in namespaces';}child.removeAttributeNode(attr);if(attr.lookupNamespaceURI('p')!==null||attr.lookupPrefix('urn:original')!==null)throw 'detached Attr has no namespace context';var empty=new Document(),fragment=xml.createDocumentFragment(),dtype=xml.implementation.createDocumentType('Root','','');for(var node of [empty,fragment,dtype]){if(uri.call(node,'xml')!==null||prefix.call(node,'urn:original')!==null)throw 'no invented namespace context';}if(document.lookupNamespaceURI(null)!=='http://www.w3.org/1999/xhtml'||document.lookupNamespaceURI('')!==document.lookupNamespaceURI(undefined)||document.lookupPrefix('http://www.w3.org/1999/xhtml')!==null)throw 'default namespace and nullable strings';
"#);
}
#[test]
fn node_namespace_lookup_declarations_default_undeclaration_order_and_exact_utf16(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var xmlns='http://www.w3.org/2000/xmlns/',xml=document.implementation.createDocument(null,'Root'),root=xml.documentElement,child=xml.createElement('Child');root.appendChild(child);root.setAttributeNS(xmlns,'xmlns:p','urn:first');root.setAttributeNS(xmlns,'xmlns:q','urn:first');root.setAttributeNS(xmlns,'xmlns','urn:default');if(child.lookupNamespaceURI('p')!=='urn:first'||child.lookupPrefix('urn:first')!=='p'||child.lookupNamespaceURI(null)!=='urn:default'||!child.isDefaultNamespace('urn:default'))throw 'first declaration and default inheritance';child.setAttributeNS(xmlns,'xmlns:p','');child.setAttributeNS(xmlns,'xmlns','');if(child.lookupNamespaceURI('p')!==null||child.lookupNamespaceURI(null)!==null||!child.isDefaultNamespace(null))throw 'explicit empty declaration stops ancestry';child.setAttributeNS(xmlns,'xmlns:p','urn:changed');if(child.lookupNamespaceURI('p')!=='urn:changed'||child.lookupPrefix('urn:changed')!=='p'||root.lookupNamespaceURI('p')!=='urn:first')throw 'nearest declaration';var exact=xml.createElementNS('urn:\ud800','n\ud800:Case');child.appendChild(exact);exact.setAttributeNS(xmlns,'xmlns:a\ud800','value\ud800');if(exact.lookupNamespaceURI('n\ud800')!=='urn:\ud800'||exact.lookupPrefix('urn:\ud800')!=='n\ud800'||exact.lookupNamespaceURI('a\ud800')!=='value\ud800'||exact.lookupPrefix('value\ud800')!=='a\ud800'||exact.lookupNamespaceURI('a\ufffd')!==null||exact.lookupPrefix('value\ufffd')!==null)throw 'exact raw namespace prefix local and declaration units';
"#);
}
#[test]
fn node_namespace_lookup_conversion_reentry_uses_current_native_tree_and_ignores_author_getters(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var xml=document.implementation.createDocument(null,'Root'),root=xml.documentElement,xmlns='http://www.w3.org/2000/xmlns/',calls=0;root.setAttributeNS(xmlns,'xmlns:p','before');Object.defineProperty(Element.prototype,'namespaceURI',{configurable:true,get:function(){throw 'author namespace getter';}});Object.defineProperty(Element.prototype,'attributes',{configurable:true,get:function(){throw 'author attribute getter';}});var value=root.lookupNamespaceURI({toString:function(){calls++;root.setAttributeNS(xmlns,'xmlns:p','after');return 'p';}});if(value!=='after'||calls!==1||root.lookupPrefix({toString:function(){calls++;return 'after';}})!=='p'||calls!==2)throw 'conversion exactly once before native current data read';var touched=0,caught=false;try{Node.prototype.lookupNamespaceURI.call({},{toString:function(){touched++;return 'p';}});}catch(e){caught=e instanceof TypeError;}if(!caught||touched)throw 'brand precedes author conversion';
"#);
}
#[test]
fn node_namespace_lookup_blank_child_facts_and_captured_origin_precede_author_conversion(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var w=frame.contentWindow,saved=w.Node.prototype.lookupNamespaceURI,read=w.Node.prototype.lookupPrefix,calls=0,query={toString:function(){calls++;return 'xml';}};if(saved.call(w.document,query)!=='http://www.w3.org/XML/1998/namespace'||calls!==1||w.document.body.lookupNamespaceURI(null)!=='http://www.w3.org/1999/xhtml'||read.call(w.document.body,'http://www.w3.org/1999/xhtml')!==null||saved.call(document,'xml')!=='http://www.w3.org/XML/1998/namespace')throw 'actual immutable blank child namespace facts';");page.set_location(&crate::navigation::address("https://other-namespace-lookup.test/",&crate::navigation::Location::home()).unwrap());let before=(doc.nodes.len(),page.state.retained,page.state.dom_commits);assert_eq!(page.console_eval(&mut doc,&mut forms,"saved.call(document,query);").errors,1);assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.retained,page.state.dom_commits),before);run(&mut doc,&mut forms,&mut page,"if(calls!==1)throw 'origin guard precedes namespace string conversion';");
}

#[test]
fn node_namespace_lookup_raw_xmlns_is_passive_data_and_active_raw_attribute_guard_remains(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"var root=document.createElement('span'),xmlns='http://www.w3.org/2000/xmlns/';root.setAttributeNS(xmlns,'xmlns:p','raw\ud800');var declaration=root.getAttributeNodeNS(xmlns,'p');if(root.lookupNamespaceURI('p')!=='raw\ud800'||root.lookupPrefix('raw\ud800')!=='p'||declaration.value!=='raw\ud800'||declaration.ownerElement!==root)throw 'actual raw namespace data';var clone=root.cloneNode(false);root.setAttributeNS(xmlns,'xmlns:p','changed');if(clone.lookupNamespaceURI('p')!=='raw\ud800'||root.lookupNamespaceURI('p')!=='changed')throw 'raw declaration snapshot copy on write';var target=new Document(),inert=target.importNode(clone,false);if(inert.lookupNamespaceURI('p')!=='raw\ud800'||inert.getAttributeNodeNS(xmlns,'p').ownerDocument!==target)throw 'raw declaration inert transfer';var image=document.createElement('img');"#);let before=(doc.nodes.len(),page.state.dom_commits);assert_eq!(page.console_eval(&mut doc,&mut forms,r#"image.setAttribute('src','https://no-raw-resource.test/\ud800');"#).errors,1);assert_eq!((doc.nodes.len(),page.state.dom_commits),before);run(&mut doc,&mut forms,&mut page,"if(image.getAttribute('src')!==null||root.lookupNamespaceURI('p')!=='changed'||inert.lookupPrefix(inert.lookupNamespaceURI('p'))!=='p')throw 'active raw refusal preserves actual passive data';");assert!(!page.has_navigation_request());assert!(page.take_dynamic_scripts().is_empty()&&page.take_dynamic_stylesheets().is_empty());let(a,b,c)=page.take_image_changes();assert!(a.is_empty()&&b.is_empty()&&c.is_empty());
}
